logic:
// p1 _version, p6 _debug 미사용. p2 rnd 는 strategy() 로 통과 전달만.
ctx = data.context                       // OperationData+0x8

// --- 544 ---
if !rule_scope::line_exists(ctx, line) { return false }

// --- 549 : rule_scope::morgard_exists 가 통째로 인라인됨 ---
//     본문에 남은 것은 TutorialType::spawn_epic(runner.rs:262) 의 범위검사뿐
if (ctx.tutorial - 1) <u 6 { return false }      // tutorial ∈ 1..=6 이면 종료. 0/7/8 만 통과

// --- 549 (같은 줄) : 게임모드 취득 + 에픽 잔여시간 게이트 ---
cache = data.cache                       // &AbstractGameWithCache
game  = cache.game                       // dyn: obj=+0x0, vtable=+0x8
mode  = vtable[+0x40](game.obj)          // -> enum2$<GameMode> { i64 tag, ptr payload }
if mode.tag != 0 { core::option::unwrap_failed() }   // GameMode::as_moba(game.rs:230).unwrap()
moba  = mode.payload                     // &MobaMode
team  = player.info.team                 // PlayerState+0x930
other = 1 - team                         // 상대 팀 (>=2 면 panic_bounds_check)
if moba.remain_epic_time[other] == 0 { return false }   // MobaMode+0x240 + other*8

// --- 553 : AbstractGameWithCache::tower(line, team) 인라인 ---
switch line {                             // 판별자는 switch 로 접혀 사라짐
  Top    => (a,b) = (0x180, 0x190)
  Mid    => (a,b) = (0x1a0, 0x1b0)
  Bottom => (a,b) = (0x1c0, 0x1d0)
}
if team >= 2 { panic_bounds_check }
line_tower = cache[a][team].or(cache[b][team])        // Option::or (option.rs:1618) — 1순위 우선

// --- 554~559 : 트윈타워 중 라인 시작점에 가장 가까운 것 ---
tw = cache.twin_towers[team]              // +0x130 + team*32, Vec<&Entity>{ptr@+0x0, len@+0x18}
nearest = if tw.len == 0 { None } else {
    tw.iter().min_by_key(|e| {            // 첫 원소는 인라인 전개, 나머지는 m12 의 fold 로
        (sx, sy) = LineType::get_start_position(line, ctx.setting, player.info.team)   // 556
        dx = abs_diff(e.x, sx); dy = abs_diff(e.y, sy)                                 // 557
        dx*dx + dy*dy                     // key = 제곱거리
    })                                    // 동점이면 앞선 원소 유지(compare<=0 시 기존 유지)
}
tower_opt = line_tower.or(nearest.map(|x| *x))       // 559
if tower_opt.is_none() { return false }               // 565 (뒤이은 unwrap 은 LLVM 이 무해화)
tower = tower_opt.unwrap()

// --- 567 ---
if !has_line_defense_threat(player, data, line, tower.id /*Entity+0x5c0*/) { return false }

// --- 571~572 ---
enemies = cache.champions(other, ctx.pool)            // bumpalo Vec<&Entity>, 상대 팀
near_enemy_champion = 0
for c in enemies {
    if data.blackboard[other].is_recent_visible(game /*dyn 2워드*/, player, c)          // 572
       && (Entity::distance_sq(tower, c) <u 40000000001)  // 200000^2+1 → 실거리 <= 200000
    { near_enemy_champion += 1 }
}
drop(enemies)

// --- 575~578 ---
strategy = PlayerState::strategy(player, rnd, game)   // Strategy 24B
defense  = strategy.morgard_defense                   // Strategy+0xe
return match defense {
    Battle (1) => (near_enemy_champion - 1) <u 2,     // 근처 적이 1명 또는 2명일 때만 true
    Gather (0) => near_enemy_champion >u 1,           // 근처 적이 2명 이상이면 true
}
// (%173 은 select i1 %is_battle, %171, %172 로 접혀 있음)
